const std = @import("std");
const tensor_mod = @import("../tensor/tensor.zig");
const dtype_mod = @import("../tensor/dtype.zig");
const config_mod = @import("../util/config.zig");
const kernels = @import("../kernels/efla_kernels.zig");

pub const EflaError = error{
    InvalidDimensions,
    OutOfMemory,
    ShapeMismatch,
    UnsupportedDevice,
    InvalidDType,
};

pub const EflaState = struct {
    state: *tensor_mod.Tensor,
    batch_size: usize,
    num_heads: usize,
    state_dim: usize,
    value_dim: usize,
    allocator: std.mem.Allocator,
    device: tensor_mod.Device,
    device_id: i32,

    pub fn init(
        allocator: std.mem.Allocator,
        batch_size: usize,
        num_heads: usize,
        state_dim: usize,
        value_dim: usize,
        device: tensor_mod.Device,
        device_id: i32,
    ) !*EflaState {
        if (batch_size == 0 or num_heads == 0 or state_dim == 0 or value_dim == 0) return EflaError.InvalidDimensions;

        const self = try allocator.create(EflaState);
        errdefer allocator.destroy(self);

        var shape_arr = [_]usize{ batch_size, num_heads, state_dim, value_dim };
        const state_shape = tensor_mod.Shape.init(&shape_arr);

        const state_tensor = try tensor_mod.Tensor.zeros(allocator, state_shape, .fp32, device, device_id);

        self.* = .{
            .state = state_tensor,
            .batch_size = batch_size,
            .num_heads = num_heads,
            .state_dim = state_dim,
            .value_dim = value_dim,
            .allocator = allocator,
            .device = device,
            .device_id = device_id,
        };

        return self;
    }

    pub fn deinit(self: *EflaState) void {
        self.state.deinit();
        self.allocator.destroy(self);
    }

    pub fn reset(self: *EflaState) !void {
        try self.state.zero_();
    }

    pub fn clone(self: *const EflaState) !*EflaState {
        const new_state_tensor = try self.state.clone(self.allocator);
        errdefer new_state_tensor.deinit();

        const cloned = try self.allocator.create(EflaState);
        cloned.* = .{
            .state = new_state_tensor,
            .batch_size = self.batch_size,
            .num_heads = self.num_heads,
            .state_dim = self.state_dim,
            .value_dim = self.value_dim,
            .allocator = self.allocator,
            .device = self.device,
            .device_id = self.device_id,
        };

        return cloned;
    }
};

pub const EflaLayer = struct {
    config: config_mod.EflaConfig,
    hidden_dim: usize,
    num_heads: usize,
    head_dim: usize,
    w_q: *tensor_mod.Tensor,
    w_k: *tensor_mod.Tensor,
    w_v: *tensor_mod.Tensor,
    w_o: *tensor_mod.Tensor,
    beta_param: ?*tensor_mod.Tensor,
    allocator: std.mem.Allocator,
    device: tensor_mod.Device,
    device_id: i32,

    pub fn init(
        allocator: std.mem.Allocator,
        config: config_mod.EflaConfig,
        hidden_dim: usize,
        num_heads: usize,
        head_dim: usize,
        device: tensor_mod.Device,
        device_id: i32,
        rng: *std.rand.Random,
    ) !*EflaLayer {
        if (hidden_dim == 0 or num_heads == 0 or head_dim == 0) return EflaError.InvalidDimensions;
        if (hidden_dim % num_heads != 0) return EflaError.ShapeMismatch;

        const self = try allocator.create(EflaLayer);
        errdefer allocator.destroy(self);

        const scale: f32 = @sqrt(2.0 / @as(f32, @floatFromInt(hidden_dim)));

        var w_q_arr = [_]usize{ hidden_dim, num_heads * head_dim };
        const w_q_shape = tensor_mod.Shape.init(&w_q_arr);
        const w_q = try tensor_mod.Tensor.randNormal(allocator, w_q_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_q.deinit();

        var w_k_arr = [_]usize{ hidden_dim, num_heads * head_dim };
        const w_k_shape = tensor_mod.Shape.init(&w_k_arr);
        const w_k = try tensor_mod.Tensor.randNormal(allocator, w_k_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_k.deinit();

        var w_v_arr = [_]usize{ hidden_dim, num_heads * head_dim };
        const w_v_shape = tensor_mod.Shape.init(&w_v_arr);
        const w_v = try tensor_mod.Tensor.randNormal(allocator, w_v_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_v.deinit();

        var w_o_arr = [_]usize{ num_heads * head_dim, hidden_dim };
        const w_o_shape = tensor_mod.Shape.init(&w_o_arr);
        const w_o = try tensor_mod.Tensor.randNormal(allocator, w_o_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_o.deinit();

        var beta_param: ?*tensor_mod.Tensor = null;
        if (config.learned_beta) {
            var beta_arr = [_]usize{1};
            const beta_shape = tensor_mod.Shape.init(&beta_arr);
            beta_param = try tensor_mod.Tensor.full(allocator, beta_shape, .fp32, device, device_id, config.initial_beta);
        }
        errdefer if (beta_param) |bp| bp.deinit();

        self.* = .{
            .config = config,
            .hidden_dim = hidden_dim,
            .num_heads = num_heads,
            .head_dim = head_dim,
            .w_q = w_q,
            .w_k = w_k,
            .w_v = w_v,
            .w_o = w_o,
            .beta_param = beta_param,
            .allocator = allocator,
            .device = device,
            .device_id = device_id,
        };

        return self;
    }

    pub fn deinit(self: *EflaLayer) void {
        self.w_q.deinit();
        self.w_k.deinit();
        self.w_v.deinit();
        self.w_o.deinit();
        if (self.beta_param) |bp| bp.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(
        self: *const EflaLayer,
        input: *tensor_mod.Tensor,
        state_opt: ?*EflaState,
    ) !struct { output: *tensor_mod.Tensor, new_state: *EflaState } {
        const batch_size = input.shape.dim(0);
        const seq_len = input.shape.dim(1);
        if (batch_size == 0 or seq_len == 0) return EflaError.InvalidDimensions;

        const q = try matmul(self.allocator, input, self.w_q);
        defer q.deinit();

        const k = try matmul(self.allocator, input, self.w_k);
        defer k.deinit();

        const v = try matmul(self.allocator, input, self.w_v);
        defer v.deinit();

        var q_shape_arr = [_]usize{ batch_size, seq_len, self.num_heads, self.head_dim };
        const q_reshaped = try q.reshape(tensor_mod.Shape.init(&q_shape_arr));
        defer q_reshaped.deinit();

        var k_shape_arr = [_]usize{ batch_size, seq_len, self.num_heads, self.head_dim };
        const k_reshaped = try k.reshape(tensor_mod.Shape.init(&k_shape_arr));
        defer k_reshaped.deinit();

        var v_shape_arr = [_]usize{ batch_size, seq_len, self.num_heads, self.head_dim };
        const v_reshaped = try v.reshape(tensor_mod.Shape.init(&v_shape_arr));
        defer v_reshaped.deinit();

        var working_state: *EflaState = undefined;
        var created_new_state = false;

        if (state_opt) |s| {
            working_state = try s.clone();
            created_new_state = true;
        } else {
            working_state = try EflaState.init(
                self.allocator,
                batch_size,
                self.num_heads,
                self.head_dim,
                self.head_dim,
                self.device,
                self.device_id,
            );
            created_new_state = true;
        }
        errdefer if (created_new_state) working_state.deinit();

        const output = try self.eflaForward(q_reshaped, k_reshaped, v_reshaped, working_state);
        defer output.deinit();

        const projected = try matmul(self.allocator, output, self.w_o);

        return .{ .output = projected, .new_state = working_state };
    }

    fn eflaForward(
        self: *const EflaLayer,
        q: *tensor_mod.Tensor,
        k: *tensor_mod.Tensor,
        v: *tensor_mod.Tensor,
        state: *EflaState,
    ) !*tensor_mod.Tensor {
        const batch_size = k.shape.dim(0);
        const seq_len = k.shape.dim(1);

        var out_shape_arr = [_]usize{ batch_size, seq_len, self.num_heads, self.head_dim };
        const output_shape = tensor_mod.Shape.init(&out_shape_arr);
        const output = try tensor_mod.Tensor.zeros(self.allocator, output_shape, .fp32, self.device, self.device_id);
        errdefer output.deinit();

        var beta: f32 = self.config.initial_beta;
        if (self.beta_param) |bp| {
            const bp_ptr = bp.typedPtr(f32) orelse return EflaError.InvalidDType;
            beta = bp_ptr[0];
        }

        switch (self.device) {
            .cuda => {
                try kernels.eflaForwardCuda(
                    q.ptr(),
                    k.ptr(),
                    v.ptr(),
                    state.state.ptr(),
                    output.ptr(),
                    batch_size,
                    seq_len,
                    self.num_heads,
                    self.head_dim,
                    beta,
                    self.config.chunk_size,
                );
            },
            else => {
                try self.eflaForwardCpu(q, k, v, state, output, beta);
            },
        }

        var res_shape_arr = [_]usize{ batch_size, seq_len, self.num_heads * self.head_dim };
        return output.reshape(tensor_mod.Shape.init(&res_shape_arr));
    }

    fn eflaForwardCpu(
        self: *const EflaLayer,
        q: *tensor_mod.Tensor,
        k: *tensor_mod.Tensor,
        v: *tensor_mod.Tensor,
        state: *EflaState,
        output: *tensor_mod.Tensor,
        beta: f32,
    ) !void {
        const batch_size = k.shape.dim(0);
        const seq_len = k.shape.dim(1);

        const q_ptr = q.typedPtr(f32) orelse return EflaError.InvalidDType;
        const k_ptr = k.typedPtr(f32) orelse return EflaError.InvalidDType;
        const v_ptr = v.typedPtr(f32) orelse return EflaError.InvalidDType;
        const s_ptr = state.state.typedPtr(f32) orelse return EflaError.InvalidDType;
        const o_ptr = output.typedPtr(f32) orelse return EflaError.InvalidDType;

        const temp_vec = try self.allocator.alloc(f32, self.head_dim);
        defer self.allocator.free(temp_vec);

        for (0..batch_size) |b| {
            for (0..self.num_heads) |h| {
                const head_state_offset = b * self.num_heads * self.head_dim * self.head_dim + h * self.head_dim * self.head_dim;

                for (0..seq_len) |t| {
                    const seq_offset = b * seq_len * self.num_heads * self.head_dim + t * self.num_heads * self.head_dim + h * self.head_dim;

                    var lambda: f32 = 0.0;
                    for (0..self.head_dim) |d| {
                        const k_val = k_ptr[seq_offset + d];
                        lambda += k_val * k_val;
                    }

                    var c_t: f32 = 0.0;
                    if (lambda < 1e-6) {
                        const beta_lambda = beta * lambda;
                        c_t = beta - (0.5 * beta * beta_lambda) + ((1.0 / 6.0) * beta * beta * beta_lambda * lambda);
                    } else {
                        c_t = (1.0 - @exp(-beta * lambda)) / lambda;
                    }

                    for (0..self.head_dim) |d_out| {
                        var sum: f32 = 0.0;
                        for (0..self.head_dim) |d_in| {
                            sum += s_ptr[head_state_offset + d_out * self.head_dim + d_in] * q_ptr[seq_offset + d_in];
                        }
                        o_ptr[seq_offset + d_out] = sum;
                    }

                    @memset(temp_vec, 0.0);
                    for (0..self.head_dim) |j| {
                        for (0..self.head_dim) |d_in| {
                            temp_vec[j] += k_ptr[seq_offset + d_in] * s_ptr[head_state_offset + d_in * self.head_dim + j];
                        }
                    }

                    for (0..self.head_dim) |i| {
                        const k_i = k_ptr[seq_offset + i];
                        const v_i = v_ptr[seq_offset + i];
                        for (0..self.head_dim) |j| {
                            const idx = head_state_offset + i * self.head_dim + j;
                            s_ptr[idx] = s_ptr[idx] - (c_t * k_i * temp_vec[j]) + (c_t * k_i * v_i);
                        }
                    }
                }
            }
        }
    }

    pub fn backward(
        self: *const EflaLayer,
        grad_output: *tensor_mod.Tensor,
        input: *tensor_mod.Tensor,
        state: *EflaState,
    ) !struct { grad_input: *tensor_mod.Tensor, grad_state: *EflaState } {
        const batch_size = input.shape.dim(0);
        const seq_len = input.shape.dim(1);

        var grad_in_arr = [_]usize{ batch_size, seq_len, self.hidden_dim };
        const grad_input = try tensor_mod.Tensor.zeros(self.allocator, tensor_mod.Shape.init(&grad_in_arr), .fp32, self.device, self.device_id);
        errdefer grad_input.deinit();

        const grad_state = try EflaState.init(
            self.allocator,
            batch_size,
            self.num_heads,
            self.head_dim,
            self.head_dim,
            self.device,
            self.device_id,
        );
        errdefer grad_state.deinit();

        if (self.device == .cpu) {
            const g_out_ptr = grad_output.typedPtr(f32) orelse return EflaError.InvalidDType;
            const g_in_ptr = grad_input.typedPtr(f32) orelse return EflaError.InvalidDType;

            for (0..batch_size) |b| {
                for (0..seq_len) |t| {
                    for (0..self.hidden_dim) |d| {
                        const idx = b * seq_len * self.hidden_dim + t * self.hidden_dim + d;
                        g_in_ptr[idx] = g_out_ptr[idx];
                    }
                }
            }
        }

        _ = state;
        return .{ .grad_input = grad_input, .grad_state = grad_state };
    }
};

fn matmul(allocator: std.mem.Allocator, a: *tensor_mod.Tensor, b: *tensor_mod.Tensor) !*tensor_mod.Tensor {
    const a_ndim = a.shape.ndim;
    const b_ndim = b.shape.ndim;

    if (a_ndim < 2 or b_ndim < 2) return EflaError.ShapeMismatch;

    const M = a.shape.dim(a_ndim - 2);
    const K = a.shape.dim(a_ndim - 1);
    const K_b = b.shape.dim(b_ndim - 2);
    const N = b.shape.dim(b_ndim - 1);

    if (K != K_b) return EflaError.ShapeMismatch;

    const batch_size = if (a_ndim > 2) a.shape.dim(0) else 1;
    const seq_len = if (a_ndim > 3) a.shape.dim(1) else if (a_ndim == 3) a.shape.dim(0) else 1;

    var out_shape_arr = [_]usize{0} ** 4;
    var out_shape: tensor_mod.Shape = undefined;

    if (a_ndim == 2) {
        out_shape_arr[0] = M;
        out_shape_arr[1] = N;
        out_shape = tensor_mod.Shape.init(out_shape_arr[0..2]);
    } else if (a_ndim == 3) {
        out_shape_arr[0] = batch_size;
        out_shape_arr[1] = M;
        out_shape_arr[2] = N;
        out_shape = tensor_mod.Shape.init(out_shape_arr[0..3]);
    } else {
        out_shape_arr[0] = batch_size;
        out_shape_arr[1] = seq_len;
        out_shape_arr[2] = M;
        out_shape_arr[3] = N;
        out_shape = tensor_mod.Shape.init(out_shape_arr[0..4]);
    }

    const output = try tensor_mod.Tensor.zeros(allocator, out_shape, .fp32, a.device, a.device_id);
    errdefer output.deinit();

    const a_ptr = a.typedPtr(f32) orelse return EflaError.InvalidDType;
    const b_ptr = b.typedPtr(f32) orelse return EflaError.InvalidDType;
    const o_ptr = output.typedPtr(f32) orelse return EflaError.InvalidDType;

    const batches = if (a_ndim > 2) batch_size * (if (a_ndim > 3) seq_len else 1) else 1;

    for (0..batches) |batch| {
        const a_offset = batch * M * K;
        const b_offset = if (b_ndim > 2) batch * K * N else 0;
        const o_offset = batch * M * N;

        for (0..M) |i| {
            for (0..N) |j| {
                var sum: f32 = 0.0;
                for (0..K) |k_idx| {
                    sum += a_ptr[a_offset + i * K + k_idx] * b_ptr[b_offset + k_idx * N + j];
                }
                o_ptr[o_offset + i * N + j] = sum;
            }
        }
    }

    return output;
}

pub const ChunkedScan = struct {
    seq_len: usize,
    chunk_size: usize,
    num_chunks: usize,

    pub fn init(seq_len: usize, chunk_size: usize) !ChunkedScan {
        if (chunk_size == 0) return EflaError.InvalidDimensions;
        return .{
            .seq_len = seq_len,
            .chunk_size = chunk_size,
            .num_chunks = (seq_len + chunk_size - 1) / chunk_size,
        };
    }

    pub fn getChunkRange(self: ChunkedScan, chunk_idx: usize) struct { start: usize, end: usize } {
        const start = chunk_idx * self.chunk_size;
        const end = @min(start + self.chunk_size, self.seq_len);
        return .{ .start = start, .end = end };
    }

    pub fn prefixScan(
        self: ChunkedScan,
        chunk_states: []*EflaState,
        allocator: std.mem.Allocator,
    ) !void {
        if (self.num_chunks == 0 or chunk_states.len < self.num_chunks) return EflaError.InvalidDimensions;

        for (1..self.num_chunks) |i| {
            const prev_state = chunk_states[i - 1];
            const curr_state = chunk_states[i];

            const prev_ptr = prev_state.state.typedPtr(f32) orelse return EflaError.InvalidDType;
            const curr_ptr = curr_state.state.typedPtr(f32) orelse return EflaError.InvalidDType;

            const total_elements = prev_state.batch_size * prev_state.num_heads * prev_state.state_dim * prev_state.value_dim;

            for (0..total_elements) |j| {
                curr_ptr[j] += prev_ptr[j];
            }
        }
        _ = allocator;
    }
};

test "EFLA state init" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    var state = try EflaState.init(gpa.allocator(), 2, 8, 64, 64, .cpu, 0);
    defer state.deinit();

    try std.testing.expectEqual(@as(usize, 2), state.batch_size);
    try std.testing.expectEqual(@as(usize, 8), state.num_heads);
    try std.testing.expectEqual(@as(usize, 64), state.state_dim);
    try std.testing.expectEqual(@as(usize, 64), state.value_dim);
}

test "ChunkedScan" {
    const scan = try ChunkedScan.init(10000, 1024);
    try std.testing.expectEqual(@as(usize, 10000), scan.seq_len);
    try std.testing.expectEqual(@as(usize, 1024), scan.chunk_size);
    try std.testing.expectEqual(@as(usize, 10), scan.num_chunks);

    const range_mid = scan.getChunkRange(5);
    try std.testing.expectEqual(@as(usize, 5120), range_mid.start);
    try std.testing.expectEqual(@as(usize, 6144), range_mid.end);

    const range_last = scan.getChunkRange(9);
    try std.testing.expectEqual(@as(usize, 9216), range_last.start);
    try std.testing.expectEqual(@as(usize, 10000), range_last.end);
}

