pub const EflaLayer = struct {
    config: config_mod.EflaConfig,
    hidden_dim: usize,
    num_heads: usize,
    head_dim: usize,
    w_q: *tensor_mod.Tensor,
    w_k: *tensor_mod.Tensor,
    w_v: *tensor_mod.Tensor,
    w_o: *tensor_mod.Tensor,
    beta_param: ?*tensor_mod.Tensor,
    allocator: std.mem.Allocator,
    device: tensor_mod.Device,
    device_id: i32,

    pub fn init(
        allocator: std.mem.Allocator,
        config: config_mod.EflaConfig,
        hidden_dim: usize,
        num_heads: usize,
        head_dim: usize,
        device: tensor_mod.Device,
        device_id: i32,
        rng: *std.rand.Random,
    ) !*EflaLayer {
        if (hidden_dim == 0 or num_heads == 0 or head_dim == 0) return EflaError.InvalidDimensions;
        if (hidden_dim % num_heads != 0) return EflaError.ShapeMismatch;

